195	// compareLiterals evaluates a comparison whose operands both folded to
196	// constants (e.g. now.getFullYear() >= 2026) into a boolean outcome.
197	func compareLiterals(left any, op ComparisonOperator, right any) (bool, error) {
198		if l, r, ok := asFloats(left, right); ok {
199			switch op {
200			case CompareEq:
201				return l == r, nil
202			case CompareNeq:
203				return l != r, nil
204			case CompareLt:
205				return l < r, nil
206			case CompareLte:
207				return l <= r, nil
208			case CompareGt:
209				return l > r, nil
210			case CompareGte:
211				return l >= r, nil
212			}
213		}
214		if l, ok := left.(string); ok {
215			if r, ok := right.(string); ok {
216				switch op {
217				case CompareEq:
218					return l == r, nil
219				case CompareNeq:
220					return l != r, nil
221				case CompareLt:
222					return l < r, nil
223				case CompareLte:
224					return l <= r, nil
225				case CompareGt:
226					return l > r, nil
227				case CompareGte:
228					return l >= r, nil
229				}
230			}
231		}
232		if l, ok := left.(bool); ok {
233			if r, ok := right.(bool); ok {
234				switch op {
235				case CompareEq:
236					return l == r, nil
237				case CompareNeq:
238					return l != r, nil
239				}
240			}
241		}
242		return false, errors.Errorf("unsupported constant comparison %T %s %T", left, op, right)
243	}
